CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS os_tenants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS os_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS os_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, name text NOT NULL, description text, CONSTRAINT os_roles_tenant_name UNIQUE (tenant_id, name));
CREATE TABLE IF NOT EXISTS os_permissions (key text PRIMARY KEY, description text NOT NULL);
CREATE TABLE IF NOT EXISTS os_role_permissions (role_id uuid NOT NULL, permission text NOT NULL, PRIMARY KEY (role_id, permission));
CREATE TABLE IF NOT EXISTS os_memberships (tenant_id uuid NOT NULL, user_id uuid NOT NULL, role_id uuid NOT NULL, status text NOT NULL DEFAULT 'active', PRIMARY KEY (tenant_id, user_id));
CREATE TABLE IF NOT EXISTS os_invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, email text NOT NULL, role_id uuid NOT NULL, expires_at timestamptz NOT NULL, accepted_at timestamptz, cancelled_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS os_audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, actor_id uuid, action text NOT NULL, entity_type text NOT NULL, entity_id uuid, metadata jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS os_ai_connections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, user_id uuid, provider text NOT NULL CHECK (provider IN ('openai', 'anthropic')), ciphertext text NOT NULL, iv text NOT NULL, auth_tag text NOT NULL, created_by uuid NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS crm_customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, name text NOT NULL, notes text, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT crm_customer_tenant_name UNIQUE (tenant_id, name));
CREATE TABLE IF NOT EXISTS crm_contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, customer_id uuid NOT NULL, name text NOT NULL, email text, phone text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS projects_projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, customer_id uuid, name text NOT NULL, status text NOT NULL DEFAULT 'planning', created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS projects_members (project_id uuid NOT NULL, tenant_id uuid NOT NULL, user_id uuid NOT NULL, access text NOT NULL DEFAULT 'member', created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (project_id, user_id));
CREATE TABLE IF NOT EXISTS projects_files (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, project_id uuid NOT NULL, name text NOT NULL, source_type text NOT NULL, source_ref text, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS projects_file_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, file_id uuid NOT NULL, version integer NOT NULL, source_metadata jsonb, checksum text, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT projects_file_version_unique UNIQUE (file_id, version));
CREATE TABLE IF NOT EXISTS knowledge_conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, project_id uuid, title text NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS knowledge_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, conversation_id uuid NOT NULL, author_id uuid NOT NULL, body text NOT NULL, source_ref text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS knowledge_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, project_id uuid, conversation_id uuid, title text NOT NULL, status text NOT NULL DEFAULT 'open', assignee_type text NOT NULL DEFAULT 'user', assignee_id uuid, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS knowledge_drafts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, project_id uuid, title text NOT NULL, body text NOT NULL, source_refs jsonb NOT NULL DEFAULT '[]'::jsonb, status text NOT NULL DEFAULT 'draft', created_by uuid NOT NULL, approved_by uuid, approved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS crm_customers_tenant_idx ON crm_customers (tenant_id);
CREATE INDEX IF NOT EXISTS projects_projects_tenant_idx ON projects_projects (tenant_id);
CREATE INDEX IF NOT EXISTS knowledge_conversations_tenant_idx ON knowledge_conversations (tenant_id);
